body.script:
// Combined JS from all files (simplified)
function navigate(page) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('page-'+page).classList.add('active');
  document.querySelectorAll('.taskbar-btn').forEach(b => b.classList.remove('active'));
  document.querySelector(`.taskbar-btn[data-tip="${page}"]`)?.classList.add('active');
}

function switchStudyTab(tab) {
  document.getElementById('study-gn-math').style.display = tab==='gn-math' ? 'grid' : 'none';
  document.getElementById('study-seraph').style.display = tab==='seraph' ? 'grid' : 'none';
  document.querySelectorAll('#page-study .btn').forEach(b => b.classList.remove('active'));
  event.target.classList.add('active');
}

// Toast helper
function showToast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2000);
}

// Keyboard shortcut for taskbar (\) – simplified
document.addEventListener('keydown', (e) => {
  if (e.key === '\\') {
    const tb = document.getElementById('taskbar');
    tb.style.display = tb.style.display === 'none' ? 'flex' : 'none';
  }
});

// Online count mock
document.addEventListener('DOMContentLoaded', () => {
  const count = document.getElementById('online-count');
  if (count) count.textContent = Math.floor(Math.random()*20)+5;
});
